// ... (содержимое файла полностью повторяет предоставленный код, до конца функции loop)

void loop() {
  unsigned long now = millis();
  processKeyboard();

  if (now - lastSensorAt >= SENSOR_INTERVAL_MS) {
    lastSensorAt = now;
    readSensors();
  }
  if (now - lastEyePullAt >= EYE_PULL_MS) {
    lastEyePullAt = now;
    fetchBlindEyeLatest();
  }
  updateBrainWaveMusic();
  updateModeMachine();
  if (now - lastSendAt >= SEND_INTERVAL_MS) {
    lastSendAt = now;
    sendBeaconData();
  }
  if (now - lastCmdAt >= COMMAND_INTERVAL_MS) {
    lastCmdAt = now;
    fetchCommand();
  }
  if (now - lastQueueFlushAt >= QUEUE_FLUSH_MS) {
    lastQueueFlushAt = now;
    flushQueue();
  }
  if (loveExperimentActive && now - lastLoraAt >= LORA_BROADCAST_MS) {
    lastLoraAt = now;
    sendLovePacketLoRa();
  }
  if (now - lastSaveAt >= AUTOSAVE_MS) {
    lastSaveAt = now;
    saveState();
    saveModel();
  }
  if (WiFi.status() != WL_CONNECTED) initWiFi(false);
  updateLED();
  if (now - lastDrawAt >= DRAW_INTERVAL_MS) {
    lastDrawAt = now;
    drawScreen();
  }
  delay(1);
}
